# Better approach: The 4s are markers, the 8-ring is the template
# Output should be: the 8-ring pattern placed at the 4s' positions
# with original 8s removed

def make_ring_pattern():
    return [
        [8, 8, 0],
        [8, 0, 8],
        [8, 8, 0]
    ]

def generate_output():
    # Start with zero grid
    result = [[0]*9 for _ in range(9)]

    # Place ring at position (4, 0) - the 4's location
    # 3x3 ring with top-left at (4,0)
    ring = make_ring_pattern()
    for r in range(3):
        for c in range(3):
            if 4+r < 9 and 0+c < 9:
                if ring[r][c] > 0:
                    result[4+r][0+c] = ring[r][c]

    # Place ring at position (7, 3) - the other 4's location
    # 3x3 ring with top-left at (7,3)
    # But this would go to row 9, which is out of bounds
    # Maybe clip it?
    for r in range(3):
        for c in range(3):
            if 7+r < 9 and 3+c < 9:
                if ring[r][c] > 0:
                    result[7+r][3+c] = ring[r][c]

    return result

result = generate_output()
print("Output:")
for row in result:
    print(row)
